from pathlib import Path
import re,json
names={'liste':['Lezzet akışı','Seçim destesi','Görsel pano','Kategori sahneleri','Mutfak rotası','Karar masası'],'detay':['Ocak başı','Tarif hikâyesi','İki alan','Hazır oldukça','Şefin sayfası','İzlemeden de pişir']}
ideas={'liste':['Tam ekran kapakları yukarı kaydır, pişireceğin tarifi seç.','Kartları geç veya kaydet; seçtiklerini aynı ekranda topla.','Değişken boyutlu yemek fotoğrafları arasında görerek keşfet.','Dikeyde kategoriler, her sahnede yatay tarifler arasında gez.','Bir dünya mutfağı seç; o mutfağın tariflerine açılan rotayı izle.','Süre, zorluk ve malzeme sayısını ayarla; seçeneklerini canlı daralt.'],'detay':['Adıma odaklan; malzemeleri gerektiğinde alttan aç.','Kapaktan hazırlığa, her adıma ayrı bir sahnede ilerle.','Yemek fotoğrafını üstte tut, tarifi alttaki çalışma alanında oku.','Hazır malzemeleri ve biten adımları tek ilerlemede birleştir.','Şefin bilgisi ve tarif notlarından hazırlığa uzanan bir okuma.','Fotoğraflı kapaktan adım rehberine geç; pişirmeyi birlikte ilerlet.']}
refs={'liste':['Dikey içerik akışı','Pinterest · kart destesi yorumu','Pinterest','Material carousel','SideChef','SideChef · Paprika'],'detay':['Pestle · Crouton','Dikey hikâye yorumu','SideChef','Paprika · Pestle','Kitchen Stories · NYT Cooking','SideChef · video kütüphanesi yorumu']}
for kind in ['liste','detay']:
 p=Path(f'v3-app/{kind}-alti.html');s=p.read_text();old=re.search(r'<main class="alternatives">(.*?)</main>',s,re.S)[1]
 cards=''.join(f'<article class="option"><div class="phone-stage"><div class="phone"><iframe src="{kind}-x{i+1}.html?gallery=1" width="390" height="844" title="X{i+1} · {name}" loading="eager"></iframe></div></div><div class="caption"><span class="letter">X{i+1}</span><div><h2>{name}</h2><p>{ideas[kind][i]}</p><p class="refs"><small>İlham</small>{refs[kind][i]}</p><a href="{kind}-x{i+1}.html" target="_blank" rel="noopener">Tek başına aç <i class="fa-solid fa-arrow-up-right-from-square" aria-hidden="true"></i></a></div></div></article>' for i,name in enumerate(names[kind]))
 content=f'<main><section><div class="set-heading"><h2>SET 1 · Aynı yapı (6)</h2><p>Canlı tasarımın altı yorumu.</p></div><div class="alternatives">{old}</div></section><section><div class="set-heading"><h2>SET 2 · Farklı yapı (6)</h2><p>Aynı tarifler ve işlevler, altı ayrı kullanım biçimi.</p></div><div class="alternatives">{cards}</div></section></main>'
 s=re.sub(r'<main class="alternatives">.*?</main>',content,s,flags=re.S).replace('Altı alternatif','İki set · On iki alternatif').replace('altı farklı yaklaşım.','iki set, on iki yaklaşım.');p.write_text(s)
Path('v3-app/verification/list-detail-set2/ideas.json').write_text(json.dumps({'names':names,'ideas':ideas,'refs':refs},ensure_ascii=False,indent=2))
